    ('23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Quiz — Question fermée, question ouverte, question indirecte', 'Allemand', '2de', 'La phrase interrogative', '65f608e5-4b91-552a-8d8c-105a3d4d7f1f'::uuid),
    ('f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Quiz — Choisir entre nicht et kein, et savoir où le poser', 'Allemand', '2de', 'La négation dans la phrase (nicht / kein)', 'd874b87d-102f-5e6f-8ec2-447b69baee4d'::uuid),
    ('132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Quiz — La conjonction envoie le verbe à la fin', 'Allemand', '2de', 'La phrase subordonnée', '08731e42-20f4-5ba9-a1d5-97dff6549114'::uuid),
    ('a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Quiz — Le genre vient d’avant, le cas vient d’après', 'Allemand', '2de', 'La phrase subordonnée relative', '0d8ede9a-283b-503a-af20-cec4d5828e7d'::uuid),
    ('c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Quiz — werden + participe II, et le fameux worden', 'Allemand', '2de', 'La phrase à la voix passive', '8a47c654-a605-5730-bba7-487ada9b17db'::uuid),
    ('d8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Quiz — zu + infinitif, et les cas où zu disparaît', 'Allemand', '2de', 'La proposition infinitive', '38a07b31-47b4-57a5-b8f8-225b69d0ae4a'::uuid),
    ('9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Quiz — der, die, das — ein, eine, ein', 'Allemand', '2de', 'Les déterminants définis et indéfinis sujets', 'bf35af9e-cf94-5597-b445-b99093492f5e'::uuid),
    ('c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Quiz — Quatre cas, deux familles de déterminants', 'Allemand', '2de', 'Les déterminants et leurs déclinaisons', 'fbcc4aac-0f1e-54b8-b62e-3aadc43061fd'::uuid),
    ('925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Quiz — ich, mich, mir — et l’ordre des pronoms', 'Allemand', '2de', 'Les pronoms personnels', 'e3a74458-8f45-5bf3-84a7-dc1997d1fa45'::uuid),
    ('38528c83-d45a-561f-b779-618a4119cb20'::uuid, 'Quiz — dieser, jener — et le der qui montre du doigt', 'Allemand', '2de', 'Les pronoms démonstratifs', '244a33f2-2a07-58f2-8284-5744a256abc0'::uuid),
    ('6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Quiz — Cinq façons de faire un pluriel', 'Allemand', '2de', 'Le pluriel des noms', '75bda0cb-8950-5cf9-ac65-264dd5171130'::uuid),
    ('066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Quiz — Après sein, werden et bleiben : rien ne bouge', 'Allemand', '2de', 'L’adjectif attribut', 'd64524d3-4a71-5442-9653-8e812c89319a'::uuid),
    ('37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Quiz — Faible, mixte, forte : qui porte la marque du cas', 'Allemand', '2de', 'L’adjectif épithète et ses déclinaisons', '489e32d7-c379-508f-a6f9-4dbed7ffe53a'::uuid),
    ('1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Quiz — sein ou ihr : c’est le possesseur qui décide', 'Allemand', '2de', 'L’adjectif possessif', 'adaa3a03-88e0-5f77-a5a1-ef125b042461'::uuid),
    ('fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Quiz — Peters Auto, das Auto des Vaters, das Auto von Peter', 'Allemand', '2de', 'Le génitif saxon', '6fe94dbf-534f-5be7-a59a-2badbbad3223'::uuid),
    ('46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Quiz — -er, als, so… wie', 'Allemand', '2de', 'Le comparatif', '645dc088-2436-5595-9618-0ed8148017f7'::uuid),
    ('b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Quiz — am schnellsten ou der schnellste', 'Allemand', '2de', 'Le superlatif', 'c8e46961-b6d5-568f-8cfe-7a6208834e3a'::uuid),
    ('d6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Quiz — durch, für, gegen, ohne, um', 'Allemand', '2de', 'Les prépositions suivies de l’accusatif', '14565c35-319d-50ad-931f-c3a16f9ca36d'::uuid),
    ('2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Quiz — aus, bei, mit, nach, seit, von, zu', 'Allemand', '2de', 'Les prépositions suivies du datif', '8165ce77-6716-528c-9683-294e8be5943c'::uuid),
    ('98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'Quiz — wo ? datif — wohin ? accusatif', 'Allemand', '2de', 'Les prépositions mixtes', 'd4e7d012-8cbf-5131-a907-c8f5ca0191af'::uuid),
    ('20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Quiz — Cinq mots qui ne touchent pas à l’ordre des mots', 'Allemand', '2de', 'Les conjonctions de coordination', '8aac945a-7a49-539b-b8d2-2d9aa944643c'::uuid),
    ('749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Quiz — wo, wohin, woher — trois questions, trois constructions', 'Allemand', '2de', 'Les compléments de lieu (locatif / directionnel)', 'c063f493-f194-5179-9c86-1b149f4a91d2'::uuid),
    ('fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Quiz — am, im, um — et l’accusatif sans préposition', 'Allemand', '2de', 'Les compléments de temps', '4b0ff200-0454-5adc-96b0-34b921792c23'::uuid),
    ('c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Quiz — sein, haben, werden : trois verbes, six emplois', 'Allemand', '2de', 'Les auxiliaires', '563930af-5c82-5f20-a7d1-d06ed896de4e'::uuid),
    ('9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Quiz — Trois formes à retenir par verbe', 'Allemand', '2de', 'Les verbes faibles et les verbes forts', '10d6cbcf-0f77-57c6-b634-6a3e29ea7310'::uuid),
    ('74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Quiz — Six verbes qui changent le sens de la phrase', 'Allemand', '2de', 'Les verbes de modalité', 'e0659923-d88b-55c9-b9de-c10acb2b7fd6'::uuid),
    ('99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Quiz — Le préverbe part à la fin — sauf quand il ne part pas', 'Allemand', '2de', 'Les verbes à préverbe séparable', 'ddbd9081-41ea-5da7-89a9-0e605e14d2ee'::uuid),
    ('ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Quiz — sich, à l’accusatif ou au datif', 'Allemand', '2de', 'Les verbes pronominaux', '59aac5b7-83c2-503a-98d9-93eb309885e3'::uuid),
    ('87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Quiz — Un seul présent, et il dit aussi le futur', 'Allemand', '2de', 'L’indicatif présent', 'dedc5a5e-0e03-52c5-9099-6b3dc03bacde'::uuid),
    ('eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quiz — Le passé de l’écrit et du récit', 'Allemand', '2de', 'Le prétérit', '81567d39-e6c2-55c5-bb8b-feb1f624aadb'::uuid),
    ('e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Quiz — Le passé qu’on parle', 'Allemand', '2de', 'Le parfait', '17d55c7f-7596-5444-ad35-b050cff5fbb8'::uuid),
    ('4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Quiz — werden + infinitif, et le présent qui suffit souvent', 'Allemand', '2de', 'Le futur', '58be6b60-5b86-5b3c-8345-41bf830d208f'::uuid),
    ('c9d5b452-a3ee-51e0-8674-6282d18b2670'::uuid, 'Quiz — Trois personnes, trois formes', 'Allemand', '2de', 'L’impératif', '96c0f338-6718-5508-bc91-1fe163d5a9c0'::uuid),
    ('724668d4-7d00-5d78-a6d1-19af9a4086f0'::uuid, 'Quiz — würde, hätte, wäre : l’irréel et la politesse', 'Allemand', '2de', 'Le subjonctif II présent', '7c6d527f-1e13-5b94-9ad9-9e91804411ba'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('f47e0557-3a57-570d-9e21-bd0d8aea4d9d'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Devant une subordonnée introduite par « dass », la virgule est…', 'mcq', '["Obligatoire","Facultative","Interdite","Remplacée par un tiret"]'::jsonb, 0, 'La virgule allemande sépare des propositions : *Ich weiß, dass er kommt.*', 1),
    ('57bc3634-4f88-54e9-80f7-072c8b76c87c'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'En allemand, on met une virgule devant « und » dans une énumération.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pas de virgule devant *und* ni *oder* ; mais elle est obligatoire devant *aber*, *sondern* et *denn*.', 2),
    ('19a28763-2364-5688-9c6c-025335a5155b'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Comment s’écrivent les guillemets allemands ?', 'mcq', '["En bas à l’ouverture, en haut à la fermeture","Avec des chevrons, comme en français","Les deux en haut, comme en anglais","Ils n’existent pas"]'::jsonb, 0, '*Er sagt: „Ich komme.“* — et deux-points avant le discours direct.', 3),
    ('d8da380a-5383-5e4d-89d0-c002da6bc698'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Quel groupe infinitif exige une virgule ?', 'mcq', '["Celui introduit par um… zu","Tout groupe contenant zu","Aucun groupe infinitif","Seulement celui introduit par dass"]'::jsonb, 0, '*Ich lerne, um zu bestehen.* Idem pour *ohne… zu* et *statt… zu*.', 4),
    ('56a00d7a-5861-5e47-b223-fe32ae6d87d7'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Un adjectif substantivé prend la majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*das Wichtigste*, *das Neue* : dès qu’un mot devient nom, il prend la majuscule.', 5),
    ('feb7b09d-d1d8-5fb7-8653-c6dd20712fed'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Qu’est-ce qui distingue « Sie » de « sie » à l’écrit ?', 'mcq', '["La majuscule du vouvoiement","L’accent sur le e","Rien du tout","La place dans la phrase"]'::jsonb, 0, 'Le *Sie* de politesse et ses formes (*Ihnen*, *Ihr*) gardent la majuscule.', 6),
    ('f8af3c63-1de1-5bef-b2f0-f2dc6c7748e9'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Après une voyelle brève, on écrit…', 'mcq', '["ss, comme dans Fluss et dass","ß, comme dans Fluß et daß","un s simple","sz"]'::jsonb, 0, '*ß* est réservé aux voyelles longues et aux diphtongues : *Straße*, *heißen*.', 7),
    ('411738ce-eee6-5387-863f-81f3a1491cc6'::uuid, '47f52bd0-8581-5b14-bf32-cfc1bede879a'::uuid, 'Une subordonnée enchâssée dans la principale est encadrée de deux virgules.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das Buch, das ich lese, ist spannend.*', 8),
    ('37f5137b-926b-5dc1-a811-2e48c46725cd'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Dans une déclarative allemande, le verbe conjugué occupe…', 'mcq', '["La deuxième place","La première place","La dernière place","N’importe quelle place"]'::jsonb, 0, 'La deuxième POSITION, c’est-à-dire le deuxième groupe, pas le deuxième mot.', 1),
    ('3e6c4182-5450-59e8-9128-9d781aa79a44'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, '« Heute er geht ins Kino » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand un autre élément ouvre la phrase, le sujet passe après le verbe : *Heute geht er…*', 2),
    ('b8dce25f-7c2d-5312-89f8-ba1ad3c0b49a'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Où se place l’infinitif dépendant d’un verbe de modalité ?', 'mcq', '["À la fin de la phrase","Juste après le modal","En première position","Avant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : *Ich muss heute Abend arbeiten.*', 3),
    ('e5fc46da-2970-5894-8c71-fe295ab07ba3'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Que signifie l’ordre TeKaMoLo ?', 'mcq', '["Temps, cause, manière, lieu","Temps, lieu, cause, manière","Lieu, temps, cause, manière","Cause, lieu, temps, manière"]'::jsonb, 0, '*Ich fahre morgen wegen der Arbeit mit dem Zug nach München.*', 4),
    ('2c1c353c-a3a5-5cf2-a97f-c140b87b167a'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Avec deux groupes nominaux, l’ordre est datif puis accusatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich gebe dem Kind das Buch.* L’ordre s’inverse si l’accusatif est un pronom.', 5),
    ('7bf1b7cc-b9c2-5221-a34e-987fda6c16e5'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Comment traduire « Je le donne à l’enfant » ?', 'mcq', '["Ich gebe es dem Kind","Ich gebe dem Kind es","Ich es gebe dem Kind","Ich gebe dem es Kind"]'::jsonb, 0, 'Le pronom accusatif remonte devant le groupe au datif.', 6),
    ('de3ffb85-5910-5aff-8389-b5bac2d0a1ae'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, 'Dans « Ich stehe um sieben Uhr auf », « auf » est…', 'mcq', '["Le préverbe séparable, rejeté en fin de phrase","Une préposition de lieu","Un adverbe de temps","Une faute de frappe"]'::jsonb, 0, '*aufstehen* : le préverbe ferme la parenthèse verbale.', 7),
    ('452d2e3d-2ead-5f01-83d8-ff500593687a'::uuid, 'cf68a000-6280-5c45-95c5-7c07b7b17781'::uuid, '« Nach Berlin fahre ich morgen » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'N’importe quel groupe peut occuper la première place, tant que le verbe garde la deuxième.', 8),
    ('7c3ba2c1-2166-5731-8272-ead6ebede1b2'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Dans une question fermée, où se place le verbe conjugué ?', 'mcq', '["En première position","En deuxième position","À la fin de la phrase","Juste après le sujet"]'::jsonb, 0, '*Kommst du morgen?* La réponse attendue est *ja*, *nein* ou *doch*.', 1),
    ('a9c153b2-c96c-5007-8964-3901f78e0a6e'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Dans une question ouverte, le verbe reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot en *w-* occupe la première place : *Wann kommst du?*', 2),
    ('4d26ec9b-011b-5585-b9e8-6a4afc360ea7'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Quelle est la forme accusative de « wer » ?', 'mcq', '["wen","wem","wessen","was"]'::jsonb, 0, '*Wen siehst du?* — *wem* est le datif, *wessen* le génitif.', 3),
    ('cf3cae11-9015-57ee-b44f-742e3cde5c0b'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Comment répondre « si ! » à « Du kommst nicht mit? »', 'mcq', '["Doch!","Ja!","Nein!","So!"]'::jsonb, 0, 'Après une question négative, *ja* est impossible : c’est *doch* qui contredit.', 4),
    ('01d16683-8869-5253-9e4b-54c44afb386e'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Dans une question indirecte, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En première position","En deuxième position","Devant le sujet"]'::jsonb, 0, '*Ich weiß nicht, wann er kommt.*', 5),
    ('a3721050-0a83-574d-8c41-bc5a62d0faff'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Le « si » d’une question indirecte se traduit par « wenn ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *ob* : *Ich frage mich, ob er kommt.* *wenn* introduit une condition ou un moment.', 6),
    ('e2d46a42-c859-5401-88c6-d59c44f5e3e1'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Que demande « wohin » ?', 'mcq', '["La destination d’un déplacement","Le lieu où l’on se trouve","Le lieu d’où l’on vient","La cause"]'::jsonb, 0, '*wo* = sans mouvement, *wohin* = vers où, *woher* = d’où.', 7),
    ('c707e9b5-e5e4-5503-a6a7-c5a057ba20fa'::uuid, '23f18ecc-cf4a-51cf-8f44-c17bab4be07b'::uuid, 'Comment demander « À quoi penses-tu ? »', 'mcq', '["Woran denkst du?","An was denkst du nicht?","Wen denkst du?","Wo denkst du?"]'::jsonb, 0, 'Pour une CHOSE, l’allemand soude *wo(r)-* et la préposition.', 8),
    ('7628f933-bd12-522b-8fae-fb8b8bca732c'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Comment nier « Ich habe ein Auto » ?', 'mcq', '["Ich habe kein Auto","Ich habe nicht ein Auto","Ich habe nicht Auto","Ich habe ein Auto nicht"]'::jsonb, 0, 'Devant un nom avec *ein* ou sans article, c’est *kein*.', 1),
    ('6f641e01-d21f-556e-96da-bd327444af55'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Comment nier « Ich kenne den Mann » ?', 'mcq', '["Ich kenne den Mann nicht","Ich kenne keinen Mann","Ich kenne den Mann kein","Ich nicht kenne den Mann"]'::jsonb, 0, 'Le nom porte un article défini : la négation est *nicht*, rejetée à droite.', 2),
    ('1d705c42-3064-5eea-a9d8-f039b7331093'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, '« kein » se décline comme « ein » et possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*keine Freunde*, *keinen Kaffee*, *keinem Kind*.', 3),
    ('af45fbc4-cdff-5fab-b45a-30d392b40096'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Où se place « nicht » par rapport à un attribut ?', 'mcq', '["Devant l’attribut","Après l’attribut","En fin de phrase","Devant le sujet"]'::jsonb, 0, '*Das Buch ist nicht interessant.*', 4),
    ('4d274821-74bc-57bd-8a22-ca7c1c5ca91d'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Dans « Ich habe ihn gestern nicht gesehen », « nicht » se place…', 'mcq', '["Devant le participe passé","Après le participe passé","Juste après l’auxiliaire","En première position"]'::jsonb, 0, '*nicht* va le plus à droite possible, mais reste devant le second morceau du verbe.', 5),
    ('2c122e24-a5bd-5fa7-94cb-782842773932'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'En allemand, la double négation renforce la négation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule négation suffit : *Ich sehe nichts.* C’est l’espagnol qui double.', 6),
    ('cf46c3c9-002a-524b-9a06-fdf506558d50'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Que signifie « nicht mehr » ?', 'mcq', '["Ne… plus","Pas encore","Jamais","Nulle part"]'::jsonb, 0, '*noch nicht* signifie « pas encore ».', 7),
    ('5942fe2b-8e65-5ba0-a5e4-104a9be3784b'::uuid, 'f7d8b914-f09f-5a6a-8bb1-85396c89bd2d'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["sondern","aber","denn","oder"]'::jsonb, 0, '*Er ist nicht Deutscher, sondern Österreicher.* *aber* oppose sans rectifier.', 8),
    ('9fd35efe-38fc-58e7-8845-b8fd42c75ad3'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Dans une subordonnée, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En deuxième position","Juste après la conjonction","En première position"]'::jsonb, 0, '*Ich bleibe zu Hause, weil ich krank bin.*', 1),
    ('137b6476-9e52-51ca-b23d-9a2a7bee1f55'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Dans « …, weil ich gearbeitet habe », quel mot ferme la phrase ?', 'mcq', '["L’auxiliaire conjugué habe","Le participe gearbeitet","Le sujet ich","La conjonction weil"]'::jsonb, 0, 'Le verbe CONJUGUÉ passe après le participe : c’est propre à la subordonnée.', 2),
    ('389664ae-87d3-57b0-b816-d8a2d46a9716'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, '« denn » envoie le verbe à la fin, comme « weil ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*denn* est une conjonction de coordination : *Ich bleibe zu Hause, denn ich bin krank.*', 3),
    ('309491b8-4504-5538-879c-f2d2c53f8304'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Si la subordonnée ouvre la phrase, que se passe-t-il dans la principale ?', 'mcq', '["Le verbe suit immédiatement la virgule","Le sujet suit immédiatement la virgule","Rien ne change","La principale perd son verbe"]'::jsonb, 0, '*Weil ich krank bin, bleibe ich zu Hause.* La subordonnée occupe la première position.', 4),
    ('0171e7f3-9268-5b59-907c-a671c79dc882'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Quelle conjonction traduit « quand » pour un fait unique du passé ?', 'mcq', '["als","wenn","wann","ob"]'::jsonb, 0, '*Als ich zehn Jahre alt war…* — *wenn* vaut pour la répétition ou le présent.', 5),
    ('1a50fe96-9a32-53d9-b51d-021d48654ff8'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, '« wann » peut introduire une subordonnée de temps ordinaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*wann* n’apparaît que dans une question, directe ou indirecte.', 6),
    ('20481fe1-6c76-5be1-b0bb-93cd564abd4d'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Que signifie « obwohl » ?', 'mcq', '["Bien que","Parce que","Pour que","Depuis que"]'::jsonb, 0, '*Obwohl es regnet, gehe ich spazieren.*', 7),
    ('930eea78-4f6b-5ef6-b1ed-d05532985e1a'::uuid, '132e29b8-dbef-5418-a7d5-cd11eecd34be'::uuid, 'Quelle conjonction exprime le but ?', 'mcq', '["damit","weil","obwohl","nachdem"]'::jsonb, 0, '*Ich lerne, damit ich das Abitur bestehe.*', 8),
    ('798ec389-2d3d-53e6-95ab-bdc4d114c58c'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Le pronom relatif prend son genre de l’antécédent et son cas…', 'mcq', '["De sa fonction dans la relative","De la fonction de l’antécédent","Du verbe de la principale","Il ne prend jamais de cas"]'::jsonb, 0, 'C’est le raisonnement en deux temps : genre avant, cas après.', 1),
    ('164cd1ff-428b-5ab1-bb12-871fcf9ae703'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Comment traduire « l’homme que je vois » ?', 'mcq', '["Der Mann, den ich sehe","Der Mann, der ich sehe","Der Mann, dem ich sehe","Der Mann, dessen ich sehe"]'::jsonb, 0, 'Masculin + fonction de COD → accusatif *den*.', 2),
    ('06959c2e-73b3-5536-a817-94a883e41b17'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Quelle est la forme du relatif au datif pluriel ?', 'mcq', '["denen","den","deren","die"]'::jsonb, 0, '*Die Freunde, denen ich helfe.* C’est l’une des trois formes qui diffèrent de l’article.', 3),
    ('c9468dbe-05e5-5e3b-b389-249b7731527c'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Dans une relative, le verbe conjugué reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La relative est une subordonnée : le verbe conjugué ferme la proposition.', 4),
    ('9bb925f0-6da8-5c21-961b-d8b5a933f025'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Où se place la préposition dans une relative ?', 'mcq', '["Devant le pronom relatif","À la fin de la relative","Après le verbe","Elle disparaît"]'::jsonb, 0, '*Die Stadt, in der ich wohne.* Et c’est elle qui commande le cas.', 5),
    ('660bed48-d6fc-54ba-a6b9-f019fec9a77f'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Comment traduire « l’homme dont la voiture est en panne » ?', 'mcq', '["Der Mann, dessen Auto kaputt ist","Der Mann, deren Auto kaputt ist","Der Mann, den Auto kaputt ist","Der Mann, wessen Auto kaputt ist"]'::jsonb, 0, 'Génitif masculin *dessen*, et le nom qui suit n’a pas d’article.', 6),
    ('00930b68-1e0b-50d5-abf9-7f651ff17656'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, 'Après « alles », « nichts » ou « etwas », le relatif est…', 'mcq', '["was","das","wer","dessen"]'::jsonb, 0, '*Alles, was du sagst, ist richtig.*', 7),
    ('0f14646a-6e0e-5dad-9ea2-f5bc43c635b7'::uuid, 'a7cc3518-14e0-5eb7-8b1a-3d4892ecc9e3'::uuid, '« deren » sert au génitif féminin et au génitif pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Die Frau, deren Sohn…* / *Die Leute, deren Kinder…*', 8),
    ('42510545-9e8f-5a16-b361-cd8743cda57b'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Avec quel auxiliaire se construit le passif d’action ?', 'mcq', '["werden","sein","haben","lassen"]'::jsonb, 0, '*Das Haus wird gebaut.* C’est *sein* qui donne le passif d’état.', 1),
    ('e0203244-659d-5e1b-9303-c0f07868e3c5'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Comment dit-on « la maison a été construite » ?', 'mcq', '["Das Haus ist gebaut worden","Das Haus ist gebaut geworden","Das Haus hat gebaut worden","Das Haus war gebaut"]'::jsonb, 0, 'Au parfait du passif, le participe de *werden* perd son *ge-* : *worden*.', 2),
    ('e7d6dc1b-7a72-563b-a1a8-76ce003ddefc'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, '« Das Haus ist gebaut » exprime…', 'mcq', '["Un résultat, un état","Une action en cours","Un futur","Une supposition"]'::jsonb, 0, 'C’est le passif d’état : la photo, pas le film.', 3),
    ('cbf2b3ca-799a-547b-b3d6-151661caf7fb'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Quel mot introduit l’agent quand c’est une personne ?', 'mcq', '["von + datif","durch + accusatif","mit + datif","für + accusatif"]'::jsonb, 0, '*Das Buch wurde von Goethe geschrieben.* *durch* introduit un moyen.', 4),
    ('6c7ab64e-7211-5331-a38f-6c736d232d6f'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'L’allemand peut mettre au passif un verbe sans complément d’objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le passif impersonnel : *Hier wird getanzt.*', 5),
    ('027d4359-88df-5a48-b12d-4608cb7a35ab'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Comment traduire « le travail doit être fait aujourd’hui » ?', 'mcq', '["Die Arbeit muss heute gemacht werden","Die Arbeit muss heute gemacht worden","Die Arbeit wird heute machen müssen","Die Arbeit ist heute gemacht müssen"]'::jsonb, 0, 'Le modal se conjugue, le passif passe à l’infinitif en fin de phrase.', 6),
    ('aa5d7d07-9a78-50a4-966e-2c6cae603826'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, '« Er ist Arzt geworden » contient un passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *werden* employé seul, au sens de « devenir » — d’où *geworden* et non *worden*.', 7),
    ('7f532402-506e-5f83-a47c-c22bc8faac9f'::uuid, 'c9bfc65e-c686-509a-86ce-8923f425a84c'::uuid, 'Quelle tournure active remplace souvent le passif à l’oral ?', 'mcq', '["man + verbe actif","es gibt","sein + zu","lassen"]'::jsonb, 0, '*Man baut ein Haus* est plus courant que *Ein Haus wird gebaut.*', 8),
    ('6abdf3aa-62f1-5afd-9e1b-ad9051d7a5de'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Où se place « zu » avec un verbe à préverbe séparable ?', 'mcq', '["Entre le préverbe et le radical, en un seul mot","Devant le préverbe","Après l’infinitif","Il disparaît"]'::jsonb, 0, '*einzukaufen*, *aufzustehen*, *anzurufen*.', 1),
    ('c22601de-383a-5afc-94f0-d2800783c950'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Après un verbe de modalité, l’infinitif prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Ich kann schwimmen.* Les modaux, *sehen*, *hören* et *lassen* refusent *zu*.', 2),
    ('7483bacc-df21-5f05-8e67-62937d7ef29b'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Comment traduire « J’apprends l’allemand pour étudier à Berlin » ?', 'mcq', '["Ich lerne Deutsch, um in Berlin zu studieren","Ich lerne Deutsch, für in Berlin studieren","Ich lerne Deutsch zu studieren in Berlin","Ich lerne Deutsch, damit in Berlin zu studieren"]'::jsonb, 0, '*um… zu* exprime le but, avec virgule obligatoire.', 3),
    ('b0d2ca46-ebbb-5ab4-b92f-7e08bbfbe51e'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Quand faut-il employer « damit » plutôt que « um… zu » ?', 'mcq', '["Quand les deux propositions n’ont pas le même sujet","Quand la phrase est négative","Quand le verbe est séparable","Jamais"]'::jsonb, 0, '*Ich erkläre es, damit du es verstehst.*', 4),
    ('61bc8a3b-973b-50f5-bb8b-b880d915d9bd'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Que signifie « ohne etwas zu sagen » ?', 'mcq', '["Sans rien dire","Au lieu de parler","Pour ne rien dire","En disant quelque chose"]'::jsonb, 0, '*statt… zu* signifie « au lieu de ».', 5),
    ('59bd1e5f-4554-5f29-be1b-539ab0fa07b2'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, '« Ich habe viel zu tun » signifie…', 'mcq', '["J’ai beaucoup à faire","Je dois être fait","Je fais beaucoup","J’aime beaucoup faire"]'::jsonb, 0, '*haben + zu* a une valeur active ; *sein + zu* une valeur passive.', 6),
    ('9adf4537-1db1-5e19-812a-d7b37d2b17c1'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, '« Die Arbeit ist heute zu machen » a une valeur passive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle équivaut à *Die Arbeit muss heute gemacht werden.*', 7),
    ('6472dd83-2214-50c3-95ca-eca6ed0272b5'::uuid, 'd8b9e913-80a7-52b7-b303-63c68048c30a'::uuid, 'Après « Ich gehe », le verbe suivant prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les verbes de mouvement s’en passent : *Ich gehe schwimmen.*', 8),
    ('b9c221bd-8883-5431-9189-6c208bc376f5'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Quel est l’article défini neutre ?', 'mcq', '["das","der","die","den"]'::jsonb, 0, '*das Buch*, *das Haus*, *das Kind*.', 1),
    ('bb846995-4710-5d91-815d-50a4f2eacdd4'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Au pluriel, l’article défini est « die » pour les trois genres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*die Männer*, *die Frauen*, *die Kinder*.', 2),
    ('b732dc23-86c6-50bf-afd2-208070fbd186'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Quel est le genre de « Mädchen » ?', 'mcq', '["Neutre","Féminin","Masculin","Il n’en a pas"]'::jsonb, 0, 'Tous les diminutifs en *-chen* et *-lein* sont neutres, quel que soit le sens.', 3),
    ('b4580064-ae22-5819-bd23-eef9dd2bbee3'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Les noms en -ung sont généralement…', 'mcq', '["Féminins","Masculins","Neutres","Sans genre"]'::jsonb, 0, '*die Zeitung*, *die Wohnung*, *die Meinung*. Comme les noms en *-heit* et *-keit*.', 4),
    ('62fc916c-2322-5347-83a5-5bcb7b40f828'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'L’article indéfini « ein » possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit simplement *Ich sehe Kinder*. Seule sa négation *kein* a un pluriel.', 5),
    ('99bf13cc-d219-5701-9d8a-c220468332d0'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'À quel cas se met le sujet de la phrase ?', 'mcq', '["Au nominatif","À l’accusatif","Au datif","Au génitif"]'::jsonb, 0, 'C’est la forme du dictionnaire : *Der Hund schläft.*', 6),
    ('da0938af-a90a-52ad-acd6-a9bfb46411f7'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Comment traduire « il est professeur » ?', 'mcq', '["Er ist Lehrer","Er ist ein Lehrer","Er ist der Lehrer","Er ist einen Lehrer"]'::jsonb, 0, 'Pas d’article devant un nom de métier après *sein* ou *werden*.', 7),
    ('349f7efc-c3d7-5015-b2d3-d82dc9f1b71f'::uuid, '9ed3b331-bcc4-5bc1-a170-bc5e6e3740f2'::uuid, 'Dans « Das ist mein Buch », « das » est un article neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un démonstratif invariable qui signifie « ça » : il ne s’accorde à rien.', 8),
    ('f2b54b51-f585-554f-af5b-4674e3808899'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'À quel cas se met le complément d’objet direct ?', 'mcq', '["À l’accusatif","Au datif","Au nominatif","Au génitif"]'::jsonb, 0, 'Le datif est celui du complément d’objet second.', 1),
    ('ed341d35-703d-5f59-8e4f-a72224893f99'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Que devient « der » au datif ?', 'mcq', '["dem","den","des","der"]'::jsonb, 0, '*mit dem Mann*. *den* est l’accusatif, *des* le génitif.', 2),
    ('1fa33093-dcaa-5ff4-b553-1011baf65696'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Que devient « die » (féminin) au datif ?', 'mcq', '["der","dem","den","die"]'::jsonb, 0, 'Piège classique : *der* est à la fois le masculin nominatif et le féminin datif.', 3),
    ('41eaac3d-2f04-5f76-b5a6-031710fa2281'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Au datif pluriel, le nom prend un -n supplémentaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*mit den Kindern*, *aus den Ländern*.', 4),
    ('01e2b025-2153-59d8-b763-bcf58f7cdb1d'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Les possessifs se déclinent comme…', 'mcq', '["ein et kein","l’article défini","les adjectifs forts","ils ne se déclinent pas"]'::jsonb, 0, 'D’où leur nom de « déterminants en ein- » : *meinen Bruder*, *meiner Schwester*.', 5),
    ('37ecad0a-d9e7-562b-80be-5a82389ae77c'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, '« dieser » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*. Comme *jeder* et *welcher*.', 6),
    ('e8de3408-a1ca-53cb-aa52-758fccb8758c'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Au génitif masculin, le nom prend…', 'mcq', '["-(e)s","-n","-er","rien du tout"]'::jsonb, 0, '*das Auto des Vaters*, *das Ende des Jahres*.', 7),
    ('39c33adf-2ed0-588c-8115-65aebea3addb'::uuid, 'c18c8941-5dd2-5752-9853-f75a5fbcc4a2'::uuid, 'Quel genre change entre le nominatif et l’accusatif ?', 'mcq', '["Le masculin seul","Le féminin seul","Le neutre seul","Les trois genres"]'::jsonb, 0, '*der* → *den*, *ein* → *einen*. Féminin, neutre et pluriel ne bougent pas.', 8),
    ('b99ae157-4d38-5df6-a2e2-9aadacd600b1'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Quel est le pronom accusatif de « er » ?', 'mcq', '["ihn","ihm","sie","es"]'::jsonb, 0, '*Ich sehe ihn.* *ihm* est le datif.', 1),
    ('dec25333-b49c-5339-bf67-b45d21a93ebc'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Comment reprendre « der Tisch » par un pronom ?', 'mcq', '["er","es","sie","ihn"]'::jsonb, 0, 'Le genre GRAMMATICAL commande : un objet masculin se reprend par *er*.', 2),
    ('1f30ffb2-c968-5aef-846a-a9fabb9af78f'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Quel est le pronom datif de « sie » (elle) ?', 'mcq', '["ihr","ihn","ihnen","sie"]'::jsonb, 0, '*Ich helfe ihr.* Ne pas le confondre avec *ihr* = vous (2e personne du pluriel).', 3),
    ('a4aabca7-2c4c-56ec-8acd-40e2924b5824'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Avec deux pronoms compléments, l’ordre est…', 'mcq', '["Accusatif puis datif","Datif puis accusatif","Indifférent","Toujours alphabétique"]'::jsonb, 0, '*Ich gebe es dir* — l’inverse de l’ordre des groupes nominaux.', 4),
    ('48908f6d-ff08-5f8b-a1d7-8fa1fa7cf146'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, '« Sie » de politesse se conjugue comme la 3e personne du pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Können Sie mir helfen?* Et il garde toujours sa majuscule.', 5),
    ('30bbc727-7900-5eeb-bc94-942cf50d2555'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Dans « Es regnet », « es » est…', 'mcq', '["Un sujet apparent","Un COD","Un possessif","Une faute"]'::jsonb, 0, 'Comme dans *Es gibt* : un sujet grammatical vide.', 6),
    ('f94a57a1-bbb2-5192-ad83-af238a1432e4'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, '« man » se décline « einen » à l’accusatif et « einem » au datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das macht einen müde.* C’est un pronom indéfini, pas un pronom personnel.', 7),
    ('6be491f2-8a5f-5b82-b9a8-0ae09668ca49'::uuid, '925f2d7e-5f19-5bd4-9c63-326a063efac7'::uuid, 'Où remontent les pronoms compléments dans la phrase ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Avant le verbe conjugué","Après le participe passé"]'::jsonb, 0, '*Gestern hat mich mein Vater angerufen* : ils peuvent même précéder le sujet nominal.', 8),
    ('7bbb2b23-f4c7-59a4-beb7-d96da3ddbf05'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, '« dieser » se décline comme…', 'mcq', '["L’article défini","L’article indéfini","Un adjectif fort","Il ne se décline pas"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*.', 1),
    ('8be074ec-4fd7-5149-bcbe-9f52dee3699d'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, 'Dans « Den kenne ich gut! », « den » est…', 'mcq', '["Un démonstratif accentué","Un article défini","Un pronom relatif","Une préposition"]'::jsonb, 0, 'C’est la forme démonstrative la plus courante à l’oral.', 2),
    ('3b633349-39ff-58e0-af5e-467ced58e57b'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, 'Quelle est la forme du démonstratif au datif pluriel ?', 'mcq', '["denen","den","dessen","deren"]'::jsonb, 0, 'Comme le pronom relatif : *denen* et non *den*.', 3),
    ('aa5a79ab-2469-534a-b281-3fb83d912f91'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, '« Ich traf Paul und dessen Bruder » signifie…', 'mcq', '["Le frère de Paul","Mon frère","Le frère de quelqu’un d’autre","Le même frère"]'::jsonb, 0, '*dessen* lève l’ambiguïté que *seinen* laisserait planer.', 4),
    ('5cf4aabe-8e82-5b23-b080-455535783dd8'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, '« derselbe » se décline sur ses deux morceaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in demselben Haus* : *der-* comme l’article, *-selbe* comme un adjectif faible.', 5),
    ('275ab0e9-b03c-5337-a12b-64ac1dba7b92'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, 'Comment traduire « Ce sont mes parents » ?', 'mcq', '["Das sind meine Eltern","Die sind meine Eltern","Das ist meine Eltern","Diese sind meine Eltern"]'::jsonb, 0, '*das* reste invariable ; le verbe s’accorde avec ce qui suit.', 6),
    ('9ed80b7b-eb33-59a7-8454-df953b1d5ac3'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, '« dass » et « das » s’emploient indifféremment.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*dass* est la conjonction « que » ; *das* l’article ou le démonstratif. Test : remplacer par *dieses*.', 7),
    ('e9590d36-4c4d-59df-995a-e141d15050e0'::uuid, '38528c83-d45a-561f-b779-618a4119cb20'::uuid, '« jener » appartient surtout…', 'mcq', '["À la langue écrite et soutenue","À l’oral familier","Au vocabulaire technique","Au vieil allemand disparu"]'::jsonb, 0, 'À l’oral, on lui préfère *dieser… der da*.', 8),
    ('be2df54b-8509-54d8-b43f-11981da71dc0'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Quel est le pluriel de « das Buch » ?', 'mcq', '["die Bücher","die Buche","die Buchs","die Buchen"]'::jsonb, 0, 'Pluriel en *-er* avec inflexion, typique des neutres.', 1),
    ('f95eb448-a9ef-5950-8322-4377b4aa22fb'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'La quasi-totalité des féminins font leur pluriel en…', 'mcq', '["-(e)n","-e","-er","-s"]'::jsonb, 0, '*die Frauen*, *die Blumen*, *die Zeitungen* — et jamais d’inflexion.', 2),
    ('edfd602f-5122-5a3a-a027-e0c85effeade'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, '« der Lehrer » a le même mot au singulier et au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les masculins en *-er*, *-el*, *-en* ne changent pas : seul l’article le dit.', 3),
    ('32231a25-f1ef-5e51-83a1-0fefd66c777f'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Quel est le pluriel de « das Auto » ?', 'mcq', '["die Autos","die Auten","die Autoer","die Aute"]'::jsonb, 0, 'Les emprunts font leur pluriel en *-s*.', 4),
    ('a61f1724-1309-58ea-be96-a50b5e0dae78'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Au datif pluriel, que prend le nom ?', 'mcq', '["Un -n s’il n’en a pas déjà un","Un -s","Un -er","Rien"]'::jsonb, 0, '*mit den Kindern*, *aus den Städten* — sauf les pluriels en *-s*.', 5),
    ('ed1340df-87b7-53da-b580-e0db10797921'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Quel est le pluriel de « die Lehrerin » ?', 'mcq', '["die Lehrerinnen","die Lehrerins","die Lehrerine","die Lehrerinen"]'::jsonb, 0, 'Les noms en *-in* doublent le n avant *-en*.', 6),
    ('3c81fca4-db24-53b4-b3e2-407bc2c16bee'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, '« die Leute » n’existe qu’au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *die Polizei* ou *die Milch* n’existent qu’au singulier.', 7),
    ('2824d2d9-791f-533f-9992-bb0c79a82fd5'::uuid, '6129260a-3a06-5590-a69c-968e771f3c9c'::uuid, 'Au pluriel, l’article défini dépend du genre du nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *die* pour les trois genres au nominatif et à l’accusatif.', 8),
    ('6547fc2e-99bf-5f0c-9c95-11068b16d6af'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Après « sein », l’adjectif attribut…', 'mcq', '["Reste invariable","S’accorde en genre","S’accorde en nombre","Prend toujours -e"]'::jsonb, 0, '*Der Mann ist alt*, *die Frau ist alt*, *die Kinder sind alt*.', 1),
    ('a8fb93bd-5141-5a53-afd9-a5a5f9a6d912'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, '« Die Frau ist alte » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’attribut ne prend aucune terminaison : *Die Frau ist alt.*', 2),
    ('bdb6d862-68b6-58fb-b210-c4c7d989fe2d'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Quel verbe n’appelle PAS un attribut invariable ?', 'mcq', '["sehen","sein","werden","bleiben"]'::jsonb, 0, '*sein*, *werden* et *bleiben* sont les trois verbes de base de l’attribut.', 3),
    ('c15c531d-e540-5fd7-af77-6f4612a31b48'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Comment traduire « une vieille femme » ?', 'mcq', '["eine alte Frau","eine alt Frau","ein alte Frau","eine alten Frau"]'::jsonb, 0, 'Devant le nom, l’adjectif est épithète : il se décline.', 4),
    ('d16af552-3997-5093-9c98-440a2ae8d4ef'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'En allemand, l’adverbe se forme avec une terminaison spéciale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le même mot sert d’adjectif et d’adverbe : *Er singt schön.*', 5),
    ('669f7e4c-3473-5e9d-bd93-1ca9e3b89ae7'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Dans « Der Zug ist schneller », la terminaison -er marque…', 'mcq', '["Le comparatif","Le masculin","Le pluriel","Le datif"]'::jsonb, 0, 'Ce n’est pas un accord : l’attribut ne s’accorde jamais.', 6),
    ('7f46e3f4-83f9-50a7-9fef-f9865e500aa6'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'Comment traduire « je trouve le livre intéressant » ?', 'mcq', '["Ich finde das Buch interessant","Ich finde das Buch interessantes","Ich finde das interessante Buch","Ich finde interessant das Buch"]'::jsonb, 0, '*finden* + COD + attribut invariable.', 7),
    ('0cd0966c-6827-5e51-822c-316922ce452d'::uuid, '066609f4-ae62-5e40-be1a-097a06cfaee0'::uuid, 'La différence entre attribut et épithète tient à la place de l’adjectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après le verbe : invariable. Devant le nom : décliné.', 8),
    ('1d329e11-c7df-5bc7-bd23-acd24d22478b'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Quand l’adjectif prend-il la déclinaison forte ?', 'mcq', '["Quand aucun déterminant ne porte la marque du cas","Après l’article défini","Après ein et kein","Jamais au pluriel"]'::jsonb, 0, '*kalter Kaffee*, *frische Milch* : l’adjectif prend les terminaisons de l’article défini.', 1),
    ('c97cf3d7-da9b-57f4-8db8-2b4bf493881c'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Comment traduire « un vieil homme » (nominatif) ?', 'mcq', '["ein alter Mann","ein alt Mann","ein alten Mann","ein alte Mann"]'::jsonb, 0, '*ein* ne marque pas le masculin nominatif : l’adjectif le fait à sa place.', 2),
    ('ac3c17e1-dfac-54e4-9f8a-b1fce282ccc2'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Après « der », l’adjectif prend seulement -e ou -en.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la déclinaison faible : *der alte Mann*, *dem alten Mann*.', 3),
    ('b29775fe-443b-5cbe-a517-abd17ba3aeca'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Comment dit-on « une vieille maison » à l’accusatif (das Haus) ?', 'mcq', '["ein altes Haus","ein alten Haus","eine alte Haus","ein alte Haus"]'::jsonb, 0, 'Neutre accusatif : *ein* ne marque rien, l’adjectif prend *-es*.', 4),
    ('339d06af-f414-5531-a7d3-570fd0837106'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Après « meinem », l’adjectif prend…', 'mcq', '["-en","-er","-es","-e"]'::jsonb, 0, 'Le possessif marque déjà le datif : *meinem alten Freund*.', 5),
    ('ea7689ad-56f5-5afe-899b-8a8160d25e2c'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, '« hoch » garde son c devant une terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein hoher Berg*, *das hohe Haus* : le *c* disparaît.', 6),
    ('126c8ef4-45df-5af1-ab93-c374afa799dc'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, 'Que devient « teuer » dans « ein … Auto » ?', 'mcq', '["teures","teueres","teuers","teuer"]'::jsonb, 0, '*teuer* et *dunkel* perdent leur *e* : *ein teures Auto*, *ein dunkles Zimmer*.', 7),
    ('6148d371-ff67-5e17-a6a4-8610a9b322ab'::uuid, '37c27c64-be0d-5046-9a99-35e033acd684'::uuid, '« rosa » et « lila » se déclinent comme les autres adjectifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les adjectifs en *-a* sont invariables : *ein rosa Kleid*.', 8),
    ('b073f41c-e951-552f-ba11-087dbdbbca01'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Comment traduire « Anna et son frère » ?', 'mcq', '["Anna und ihr Bruder","Anna und sein Bruder","Anna und seinen Bruder","Anna und ihre Bruder"]'::jsonb, 0, 'Le radical suit le POSSESSEUR (Anna → *ihr-*), la terminaison l’objet possédé (*Bruder*, masculin).', 1),
    ('8de8f5b5-2a71-5aa9-96c0-665bbecfcc2c'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Comment traduire « Peter et sa sœur » ?', 'mcq', '["Peter und seine Schwester","Peter und ihre Schwester","Peter und sein Schwester","Peter und ihren Schwester"]'::jsonb, 0, 'Radical *sein-* (Peter), terminaison féminine (*Schwester*).', 2),
    ('506c342c-9d1d-5b62-bee9-9c950e2e908e'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Le possessif se décline comme…', 'mcq', '["ein et kein","l’article défini","un adjectif faible","il ne se décline pas"]'::jsonb, 0, 'Avec en plus un pluriel : *meine Freunde*, *meinen Freunden*.', 3),
    ('fca89d68-ba3f-5cd5-af40-f6bd8d706cfe'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Que devient « euer » devant une terminaison ?', 'mcq', '["eur-","euer-","eue-","eur-e-"]'::jsonb, 0, '*eure Mutter*, *euren Vater*. *unser*, lui, garde son *e*.', 4),
    ('81a26019-71d1-5eb4-b780-ab20bd13085a'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, '« Ihr » avec majuscule signifie « leur ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec majuscule, c’est le possessif de politesse : « votre ».', 5),
    ('7bff5354-539d-52f8-bf73-e40e63adc5e6'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Comment dit-on « je me lave les mains » ?', 'mcq', '["Ich wasche mir die Hände","Ich wasche meine Hände mir","Ich wasche mich die Hände","Ich wasche meinen Händen"]'::jsonb, 0, 'Avec les parties du corps, l’allemand préfère article + datif au possessif.', 6),
    ('03083437-3890-544b-be3a-ad9e581dee53'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Employé seul, « mein » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das ist meins*, *Das ist meiner* : il devient pronom possessif.', 7),
    ('9661fff6-282d-593c-a456-7d2fc8743a62'::uuid, '1b1148b9-e529-5436-a162-528c06c5ca01'::uuid, 'Dans « Das Kind und seine Mutter », pourquoi « seine » ?', 'mcq', '["Parce que « Kind » est neutre, donc radical sein-","Parce que « Mutter » est féminin","Parce que l’enfant est un garçon","Parce que c’est une exception"]'::jsonb, 0, 'Le radical suit le genre GRAMMATICAL du possesseur, pas son sexe.', 8),
    ('edd7e1e9-d9ca-59b8-886d-e4ba35ced408'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Comment dit-on « la voiture de Peter » ?', 'mcq', '["Peters Auto","Peter’s Auto","das Auto Peters","der Peter Auto"]'::jsonb, 0, 'Le nom propre passe devant, avec un *-s* sans apostrophe.', 1),
    ('c401a3ee-36e7-512c-9dd5-cdb75531bd5d'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Comment dit-on « la voiture du père » ?', 'mcq', '["das Auto des Vaters","das Auto der Vater","des Vaters das Auto","das Auto dem Vater"]'::jsonb, 0, 'Génitif masculin : *des* + nom en *-(e)s*, placé derrière.', 2),
    ('2349909f-f43d-53d4-a16f-41151a9baddb'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Au génitif féminin, le nom prend un -s.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les masculins et les neutres le prennent : *das Haus der Frau*.', 3),
    ('5cffaf22-c395-53fd-ad47-778fb9a8c9de'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Quelle question introduit le génitif ?', 'mcq', '["Wessen?","Wem?","Wen?","Wo?"]'::jsonb, 0, '*Wessen Buch ist das?*', 4),
    ('1556ed09-2790-5fd1-ba85-f6681ca4ab97'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","mit","für","bei"]'::jsonb, 0, 'Comme *wegen*, *trotz*, *statt*, *innerhalb* : *während des Sommers*.', 5),
    ('23f458f0-7c7a-5794-8ee2-a6045480afbe'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, '« ein Freund von mir » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*von* + datif remplace le génitif, surtout à l’oral.', 6),
    ('be4dcd6d-04cf-5af3-b0ca-0d4e619b5c53'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Le génitif saxon s’écrit avec une apostrophe, comme en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Annas Buch*, sans apostrophe — sauf après un son sifflant : *Thomas’ Auto*.', 7),
    ('0751b48d-5a09-5691-b45c-671d273f36ce'::uuid, 'fa003063-9f88-5cb4-98c2-7fc19514f5cb'::uuid, 'Au génitif pluriel, l’article est…', 'mcq', '["der","des","den","die"]'::jsonb, 0, '*die Bücher der Kinder*, sans marque supplémentaire sur le nom.', 8),
    ('9ca97247-c494-584e-ac14-f1aabf48c619'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Comment forme-t-on le comparatif d’un adjectif long comme « interessant » ?', 'mcq', '["interessanter","mehr interessant","am interessanten","interessant als"]'::jsonb, 0, 'Quelle que soit la longueur du mot, c’est la terminaison *-er*.', 1),
    ('733a1f83-34cb-55a0-bd2a-a93d4f327c91'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Quel mot introduit le second terme d’une comparaison d’inégalité ?', 'mcq', '["als","wie","wenn","denn"]'::jsonb, 0, '*Peter ist größer als Paul.* *wie* sert à l’égalité.', 2),
    ('1bd1cd81-c5bc-5663-ab1b-67c9f99df9fa'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Comment dit-on « aussi grand que » ?', 'mcq', '["so groß wie","so groß als","größer wie","als groß wie"]'::jsonb, 0, '*so… wie* pour l’égalité, *…-er als* pour l’inégalité.', 3),
    ('0939a1d9-bfc8-5252-8e86-c730805a2411'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Quel est le comparatif de « gut » ?', 'mcq', '["besser","guter","mehr gut","gutter"]'::jsonb, 0, 'Irrégulier, comme *viel → mehr* et *gern → lieber*.', 4),
    ('93405fd1-aa28-5b38-92f7-d300a55b4ed9'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, '« Ich trinke lieber Tee » signifie…', 'mcq', '["Je préfère le thé","Je bois beaucoup de thé","Je bois le meilleur thé","J’aimerais du thé"]'::jsonb, 0, '*lieber* est le comparatif de *gern* : c’est ainsi qu’on exprime la préférence.', 5),
    ('822d73c7-7e5c-517e-be09-32239f720aa4'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Devant un nom, le comparatif ne se décline pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein größeres Haus*, *mein älterer Bruder* : deux terminaisons se suivent.', 6),
    ('12aabd16-1bce-5180-881c-78c3678d8eb5'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, 'Comment dit-on « de plus en plus froid » ?', 'mcq', '["immer kälter","mehr und mehr kalt","so kalt wie","am kältesten"]'::jsonb, 0, '*Es wird immer kälter.* Et *je… desto* pour « plus… plus ».', 7),
    ('8486dced-406f-5a6e-ba63-d3f9f6c802e6'::uuid, '46d82042-dba0-547f-bfeb-9651bcfbb2e7'::uuid, '« mehr groß » est une façon correcte de dire « plus grand ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*mehr* traduit « plus » de quantité ; le comparatif d’un adjectif se fait en *-er*.', 8),
    ('7e64e33b-4d24-5193-a988-329d0852e587'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Quelle forme du superlatif s’emploie après « sein » ?', 'mcq', '["am + -sten","der + -ste","mehr + adjectif","so + adjectif"]'::jsonb, 0, '*Der Zug ist am schnellsten.* La forme en *der/die/das* est réservée à l’épithète.', 1),
    ('2eab04ee-b577-54ae-b0cd-0ae25d68c8fb'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Comment dit-on « le train le plus rapide » ?', 'mcq', '["der schnellste Zug","der Zug am schnellsten","am schnellsten Zug","der schneller Zug"]'::jsonb, 0, 'Épithète : article défini + adjectif au superlatif décliné.', 2),
    ('e11ad20e-d034-5b38-b792-bba3cc7138be'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Pourquoi dit-on « am ältesten » et non « am altsten » ?', 'mcq', '["On intercale un e après d, t, s, ß, z","C’est une exception unique","Le e marque le datif","Pour éviter l’Umlaut"]'::jsonb, 0, 'Un *e* de liaison rend la forme prononçable.', 3),
    ('c0fdb7bf-d0a6-5b43-9363-cfc5da0b095a'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Quel est le superlatif de « gut » ?', 'mcq', '["am besten","am gutsten","am mehrsten","am guten"]'::jsonb, 0, 'Série irrégulière : *gut → besser → am besten*.', 4),
    ('253becc2-c8dc-569b-8d84-78176e8590a5'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, '« am liebsten » signifie…', 'mcq', '["Ce que je préfère par-dessus tout","Le plus aimé de tous","Avec amour","Aussi volontiers que"]'::jsonb, 0, '*Am liebsten lese ich Krimis* — une tournure très utile pour donner son avis.', 5),
    ('1bbca467-6ed7-55a5-9dac-0e20f3627d44'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'La forme « am schnellsten » se décline devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est figée ; devant un nom, on passe à *der schnellste*.', 6),
    ('6f247842-f1af-5061-b946-4d5e1641d0ac'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Quel est le superlatif de « hoch » ?', 'mcq', '["am höchsten","am hochsten","am höhesten","am hohesten"]'::jsonb, 0, 'Comme *nah → am nächsten* : à apprendre par cœur.', 7),
    ('02feaaa0-4b6f-5473-b292-a1c7ed1b9758'::uuid, 'b0e95216-59ec-57ac-a6ab-5698fdee4718'::uuid, 'Comment introduire le complément d’un superlatif ?', 'mcq', '["von ou unter + datif","als + nominatif","wie + accusatif","für + accusatif"]'::jsonb, 0, '*Er ist der Größte von allen* / *unter seinen Freunden*.', 8),
    ('bdacd62f-9570-5918-9473-1beb0fe83d10'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Quelles prépositions régissent toujours l’accusatif ?', 'mcq', '["durch, für, gegen, ohne, um","aus, bei, mit, nach, von","an, auf, in, über, unter","wegen, trotz, während"]'::jsonb, 0, 'Une liste à apprendre en bloc : elle ne dépend jamais du sens.', 1),
    ('c557754c-82b0-593f-9409-ea9a2500c7d9'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Comment traduire « pour mon frère » ?', 'mcq', '["für meinen Bruder","für meinem Bruder","für mein Bruder","für meines Bruders"]'::jsonb, 0, '*für* + accusatif : le masculin devient *meinen*.', 2),
    ('95aefcf0-6cef-5a4d-b7a8-6fdc0f85bd93'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, '« gegen acht Uhr » signifie…', 'mcq', '["Vers huit heures","À huit heures précises","Avant huit heures","Contre huit heures"]'::jsonb, 0, 'Pour l’heure précise, c’est *um acht Uhr*.', 3),
    ('5037809e-5a0d-583b-bb21-fb6166f4a77e'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Où se place « entlang » ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Devant le verbe"]'::jsonb, 0, '*die Straße entlang* : c’est la seule de la liste à se postposer.', 4),
    ('9a1657c3-0636-5e63-a0fb-4b18a62934da'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, '« für das » se contracte en « fürs ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *durch das → durchs* et *um das → ums*.', 5),
    ('b030e4dd-55d4-505c-9f8c-bacd6762e7be'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Comment traduire « sans argent » ?', 'mcq', '["ohne Geld","ohne dem Geld","ohne das Geld haben","ohne Geldes"]'::jsonb, 0, '*ohne* se passe le plus souvent d’article.', 6),
    ('52e41805-9d16-5138-ba0b-f53d18508dd2'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, 'Comment traduire « pour apprendre » ?', 'mcq', '["um zu lernen","für lernen","für zu lernen","um lernen"]'::jsonb, 0, '*für* introduit un groupe nominal, jamais un verbe : le but se dit *um… zu*.', 7),
    ('009b1786-1a01-5142-baa4-45a36c21787a'::uuid, 'd6068da7-34b3-5a6f-ae02-06e9db4a4001'::uuid, '« bis » est souvent suivi d’une seconde préposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*bis zum Bahnhof*, *bis zur Brücke* — et c’est alors elle qui commande le cas.', 8),
    ('06b60471-fbd8-589b-81c7-2838cc379cef'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Quelle série de prépositions régit le datif ?', 'mcq', '["aus, bei, mit, nach, seit, von, zu","durch, für, gegen, ohne, um","wegen, trotz, während, statt","an, auf, hinter, in, neben"]'::jsonb, 0, 'La formule *aus-bei-mit-nach-seit-von-zu* se retient d’un bloc.', 1),
    ('d0d5bcd2-16ca-5efc-8b24-1e538003eea8'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, '« Ich komme aus der Schweiz » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*aus* impose le datif : *die Schweiz* devient *der Schweiz*.', 2),
    ('78096896-e276-5990-8889-84c8c53e990f'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'En quoi se contracte « zu der » ?', 'mcq', '["zur","zum","zud","zurd"]'::jsonb, 0, '*zur Schule*, *zur Post*. Et *zu dem → zum*.', 3),
    ('2f3df5e7-dfc8-5449-a479-9745a48a036f'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe nach dem Arzt","Ich gehe bei dem Arzt","Ich gehe in den Arzt"]'::jsonb, 0, '*zu* + personne vue comme un but ; *bei* dirait où l’on se trouve déjà.', 4),
    ('4fdaa595-32b3-5c01-ab1e-c0c9bbb6ff86'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Avec « seit », quel temps emploie-t-on en allemand ?', 'mcq', '["Le présent","Le parfait","Le prétérit","Le futur"]'::jsonb, 0, '*Ich lerne seit drei Jahren Deutsch.*', 5),
    ('d54b6818-33e0-5562-932b-84f1e0e3d99a'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Comment dit-on « je vais en Suisse » ?', 'mcq', '["Ich fahre in die Schweiz","Ich fahre nach die Schweiz","Ich fahre nach der Schweiz","Ich fahre zu Schweiz"]'::jsonb, 0, 'Les pays qui ont un article prennent *in* + accusatif ; les autres, *nach*.', 6),
    ('82682e60-4cd1-5980-96d0-6885be69b2c4'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, '« nach Hause » et « zu Hause » signifient la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*nach Hause* = vers la maison (mouvement), *zu Hause* = à la maison (sans mouvement).', 7),
    ('1be225c6-d73a-53fc-b221-9cfd1a9bb825'::uuid, '2cb4637d-0a8e-5a76-a165-c98b448a93b2'::uuid, 'Que signifie « bei » dans « beim Essen » ?', 'mcq', '["Pendant, lors de","Après","Sans","Contre"]'::jsonb, 0, '*bei* couvre aussi le moment d’une action en cours.', 8),
    ('094fd33b-a430-562e-8f13-45e45012afc7'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'Quel cas suit une préposition mixte en cas de déplacement ?', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Question *wohin?* → accusatif. Question *wo?* → datif.', 1),
    ('05aefca3-64f4-5f36-80cd-175f40fe1b18'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, '« Ich bin in der Schule » exprime…', 'mcq', '["Une localisation","Un déplacement","Une possession","Une cause"]'::jsonb, 0, 'Question *wo?* → datif.', 2),
    ('16341764-f830-5b24-872a-d293c3c03276'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'Combien y a-t-il de prépositions mixtes ?', 'mcq', '["Neuf","Cinq","Sept","Douze"]'::jsonb, 0, '*an, auf, hinter, in, neben, über, unter, vor, zwischen*.', 3),
    ('e04e648a-b01a-5347-bbb7-00ec4ebddaac'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'Quel verbe demande le datif : « stehen » ou « stellen » ?', 'mcq', '["stehen","stellen","Les deux","Aucun des deux"]'::jsonb, 0, '*stehen* décrit un état (datif) ; *stellen* un déplacement (accusatif).', 4),
    ('adc54f92-b20a-5848-a727-8530f75f746b'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, '« Ich laufe im Park » signifie que je cours à l’intérieur du parc.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in den Park* dirait que j’y entre. Ce n’est pas le verbe qui décide, mais le changement de lieu.', 5),
    ('0525038b-f387-515b-9367-c2f64a1f1ab7'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'En quoi se contracte « in das » ?', 'mcq', '["ins","im","ind","ins dem"]'::jsonb, 0, '*in dem* donne *im* : ne pas les confondre, ils n’ont pas le même cas.', 6),
    ('6435aba7-03c2-53e1-a18d-e27dbc9021d5'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, 'Comment dit-on « en janvier » ?', 'mcq', '["im Januar","in Januar","am Januar","an Januar"]'::jsonb, 0, 'Emploi figé : *im* + mois et saisons, *am* + jours et dates.', 7),
    ('675fcea1-0224-5a2d-90f5-bdb766530e2b'::uuid, '98e63a70-c340-5cb2-bd7b-d09670ab3512'::uuid, '« sich auf etwas freuen » se construit avec le datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un emploi figé à l’accusatif : *Ich freue mich auf die Ferien.*', 8),
    ('8eb3efab-680c-503a-8cd3-b3de7d4a8248'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Après « denn », où se place le verbe conjugué ?', 'mcq', '["En deuxième position, comme d’habitude","À la fin de la proposition","En première position","Juste après denn"]'::jsonb, 0, '*denn* est une coordination : il ne compte pas dans l’ordre des mots.', 1),
    ('4df27e86-04c9-52e1-bd70-9ae602717c00'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Quelle conjonction envoie le verbe à la fin ?', 'mcq', '["weil","denn","aber","und"]'::jsonb, 0, '*weil* subordonne ; *denn* coordonne, pour le même sens.', 2),
    ('f95645d6-f3a2-5a83-8903-f977e0fd9f8d'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, '« sondern » s’emploie…', 'mcq', '["Après une négation, pour rectifier","Après une affirmation","Pour exprimer la cause","Pour exprimer le but"]'::jsonb, 0, '*Das ist nicht mein Buch, sondern deins.*', 3),
    ('bb470cc3-1788-5a26-97ef-d63947dc8294'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Que signifie « weder… noch » ?', 'mcq', '["Ni… ni","Ou bien… ou bien","Non seulement… mais aussi","Certes… mais"]'::jsonb, 0, 'La phrase est déjà négative : on n’ajoute pas *nicht*.', 4),
    ('281395b6-c668-5ac0-a934-71ab464165e2'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'La virgule est obligatoire devant « aber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme devant *sondern* et *denn* ; elle est absente devant *und* et *oder*.', 5),
    ('92a61188-6108-5049-8c0e-9aa04caa7185'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Dans « Es regnet, deshalb bleibe ich zu Hause », pourquoi « bleibe » précède-t-il « ich » ?', 'mcq', '["Parce que deshalb occupe la première position","Parce que c’est une subordonnée","Parce que deshalb est une conjonction","C’est une faute"]'::jsonb, 0, '*deshalb* est un adverbe : il prend la première place et provoque l’inversion.', 6),
    ('a06b9149-3e35-53c0-98cd-894ca37d0449'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, '« entweder… oder » signifie « ou bien… ou bien ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À ne pas confondre avec *sowohl… als auch*, « aussi bien… que ».', 7),
    ('7ba890eb-aa51-5dc5-9a7c-0d4892bcecbd'::uuid, '20931aaf-9337-5203-8ad1-0895a7ffcc82'::uuid, 'Quelle conjonction s’emploie sans négation devant, pour opposer ?', 'mcq', '["aber","sondern","weder","denn"]'::jsonb, 0, '*Er ist arm, aber glücklich.* *sondern* exige une négation devant lui.', 8),
    ('deabf7e3-f084-520e-82f5-fc09ab3ac3e5'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Quelle question appelle un complément de lieu au datif ?', 'mcq', '["wo?","wohin?","woher?","wann?"]'::jsonb, 0, '*wo?* = localisation → datif. *wohin?* = déplacement → accusatif.', 1),
    ('721c5e4c-7ea0-5319-8259-92ba70a09cac'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe beim Arzt","Ich gehe nach dem Arzt","Ich gehe in Arzt"]'::jsonb, 0, '*zu* pour la destination, *bei* pour la localisation : *beim Arzt sein*.', 2),
    ('9461a5d7-0639-59dc-a09a-74ebd001d81a'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Comment dit-on « je viens de France » ?', 'mcq', '["Ich komme aus Frankreich","Ich komme von Frankreich","Ich komme nach Frankreich","Ich komme in Frankreich"]'::jsonb, 0, '*aus* + pays d’origine ; *von* marque un point de départ ou une personne.', 3),
    ('7b1f3537-936b-5855-b260-5fec9aa673b1'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, '« nach » s’emploie devant un pays qui a un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec article, c’est *in* + accusatif : *in die Schweiz*, *in die Türkei*.', 4),
    ('9edd1635-03e6-564a-88db-e4cb6287b732'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Que signifie « auf dem Land » ?', 'mcq', '["À la campagne","Sur le pays","Au bord de la mer","À l’étranger"]'::jsonb, 0, 'Et *aufs Land* pour le déplacement : *Wir fahren aufs Land.*', 5),
    ('f75b018d-abee-55c6-b88c-cabbd47f5ca6'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Que marque la particule « her » ?', 'mcq', '["Le rapprochement vers le locuteur","L’éloignement du locuteur","La répétition","Le passé"]'::jsonb, 0, '*Komm her!* — *hin* marque au contraire l’éloignement.', 6),
    ('41f2dfe7-63b5-5d71-a3a4-f0c69f1746ec'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, '« Wo gehst du hin? » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La particule de *wohin* peut se détacher et partir en fin de phrase.', 7),
    ('adb20eef-7fae-5e1c-89ba-fd4aff621f30'::uuid, '749e3dff-8d44-5532-99f1-67da43f5c59d'::uuid, 'Comment dit-on « je rentre à la maison » ?', 'mcq', '["Ich gehe nach Hause","Ich gehe zu Hause","Ich gehe in Hause","Ich gehe im Haus"]'::jsonb, 0, '*nach Hause* pour le mouvement, *zu Hause* pour l’état.', 8),
    ('74bc05dd-2412-5da6-bc36-0452814a5588'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Comment dit-on « le lundi » (un lundi précis) ?', 'mcq', '["am Montag","im Montag","um Montag","in Montag"]'::jsonb, 0, '*am* + jours et parties de la journée.', 1),
    ('99dd50a4-9597-50f5-95e2-9a58062de6c2'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Comment dit-on « en été » ?', 'mcq', '["im Sommer","am Sommer","um Sommer","in Sommer"]'::jsonb, 0, '*im* + mois, saisons et années.', 2),
    ('0df01c8a-3dd4-593f-8034-ccea39e5ee38'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Comment dit-on « à huit heures » ?', 'mcq', '["um acht Uhr","am acht Uhr","im acht Uhr","in acht Uhr"]'::jsonb, 0, '*um* + heure précise.', 3),
    ('6c2c2e5e-22be-5f41-88c0-c6b9dd74d981'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, '« jeden Tag » est au…', 'mcq', '["Accusatif, sans préposition","Datif, sans préposition","Génitif","Nominatif"]'::jsonb, 0, 'Durées et dates entières se mettent à l’accusatif nu : *letzte Woche*, *den ganzen Tag*.', 4),
    ('a4927401-a0e5-50c8-b57b-93c27754e81f'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Comment dit-on « il y a deux semaines » ?', 'mcq', '["vor zwei Wochen","seit zwei Wochen","in zwei Wochen","ab zwei Wochen"]'::jsonb, 0, '*vor* + datif pour le passé ; *in* + datif pour le futur.', 5),
    ('fe1572fc-1289-5c12-bdfe-d97b4247bb28'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, '« morgens » signifie « demain ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*morgen* = demain, *morgens* = le matin (habituellement).', 6),
    ('cdd8e8e0-ade5-5d97-bb06-01250b5d4212'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","seit","ab","bis"]'::jsonb, 0, '*während der Ferien*, *während des Sommers*.', 7),
    ('ad3534e7-833d-5600-85dd-f8a7d5e99a89'::uuid, 'fe22e1bf-48e3-5115-afd1-0c12cc3e92e1'::uuid, 'Où se place le complément de temps parmi les compléments ?', 'mcq', '["En premier","En dernier","Après le lieu","Après la manière"]'::jsonb, 0, 'C’est le *Te* de TeKaMoLo : temps, cause, manière, lieu.', 8),
    ('a0e812ed-0ad9-5855-b320-eb18737687d1'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Quel auxiliaire s’emploie au parfait avec les verbes de mouvement ?', 'mcq', '["sein","haben","werden","lassen"]'::jsonb, 0, '*Ich bin gefahren*, *ich bin gegangen*.', 1),
    ('276a78bb-548d-55d5-b313-98c667df2e7b'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Quel est le prétérit de « haben » à la 1re personne ?', 'mcq', '["ich hatte","ich habte","ich hatt","ich war"]'::jsonb, 0, 'Verbe mixte : radical modifié + terminaison faible.', 2),
    ('a3df7667-7e7c-5dcf-9e2f-850cd26c077c'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, '« werden » sert d’auxiliaire au futur ET au passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich werde kommen* (futur) / *Das Haus wird gebaut* (passif).', 3),
    ('02421b68-0d99-5cbf-9855-0fa442a1ea86'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Comment se conjugue « sein » à la 2e personne du pluriel ?', 'mcq', '["ihr seid","ihr sind","ihr seit","ihr bist"]'::jsonb, 0, '*seid* avec un d — *seit* avec un t est la préposition « depuis ».', 4),
    ('87426217-1ccf-5a27-9147-7a5101790970'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Que signifie « bekommen » ?', 'mcq', '["Recevoir","Devenir","Venir","Convenir"]'::jsonb, 0, 'Faux ami classique : « devenir » se dit *werden*.', 5),
    ('67f268c6-a334-539a-a350-497d748d474d'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, '« Ich habe das Auto gefahren » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Employé avec un COD, un verbe de mouvement prend *haben*.', 6),
    ('928381b7-d14d-5bb1-bbd3-8a544cb8ba88'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Quel est le participe passé de « werden » dans un passif ?', 'mcq', '["worden","geworden","gewerdet","werdet"]'::jsonb, 0, '*geworden* est réservé au verbe plein : *Er ist Arzt geworden.*', 7),
    ('62a4e329-9617-53a7-88d0-1510896ddeca'::uuid, 'c4ce50d1-cde8-58fd-a09e-2a913e0d0e7d'::uuid, 'Quel auxiliaire prend « bleiben » au parfait ?', 'mcq', '["sein","haben","werden","les deux au choix"]'::jsonb, 0, '*Ich bin zu Hause geblieben*, comme *sein* et *passieren*.', 8),
    ('d2db07bc-b9a0-518a-936f-7e25411f8989'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Qu’appelle-t-on les trois temps primitifs d’un verbe ?', 'mcq', '["Infinitif, prétérit, participe II","Présent, futur, passé","Infinitif, présent, parfait","Radical, préverbe, terminaison"]'::jsonb, 0, 'Avec eux, toute la conjugaison se déduit.', 1),
    ('3b698e23-90e8-541d-9671-625f5c71f8b4'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Quel est le participe passé de « spielen » ?', 'mcq', '["gespielt","gespielen","spielte","gespiel"]'::jsonb, 0, 'Verbe faible : *ge-* + radical + *-t*.', 2),
    ('7faca95b-4135-5247-bc8d-f72628e8eb96'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Un verbe fort change de voyelle au prétérit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’alternance vocalique : *sprechen → sprach*, *fahren → fuhr*.', 3),
    ('22fe8dc6-37c5-5718-8cbe-1098615b0e21'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Comment se conjugue « geben » à la 3e personne du singulier ?', 'mcq', '["er gibt","er gebt","er gab","er gibst"]'::jsonb, 0, 'Alternance *e → i* aux 2e et 3e personnes du singulier seulement.', 4),
    ('c253c9e4-f1bd-51b6-9590-79092d814dff'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Comment se conjugue « fahren » à la 2e personne du singulier ?', 'mcq', '["du fährst","du fahrst","du fuhrst","du fährt"]'::jsonb, 0, 'Alternance *a → ä*, qui disparaît au pluriel.', 5),
    ('103fbd78-2b37-5e44-82b4-5fc891e56b90'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, '« bringen → brachte → gebracht » est un verbe…', 'mcq', '["Mixte","Faible régulier","Fort","Irrégulier isolé"]'::jsonb, 0, 'Radical modifié mais terminaisons faibles, comme *denken* et *wissen*.', 6),
    ('8cab4d0e-000c-5f80-a0b9-a215fc6aae33'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Les verbes en -ieren prennent « ge- » au participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*studiert*, *telefoniert*, *fotografiert* : jamais de *ge-*.', 7),
    ('751bbbf2-2841-5a51-91ed-bf01f1daba65'::uuid, '9d492609-f1b6-57f6-90cf-2513c905a50f'::uuid, 'Quel est le prétérit de « schreiben » ?', 'mcq', '["schrieb","schreibte","schrob","geschrieben"]'::jsonb, 0, 'Verbe fort : *schreiben → schrieb → geschrieben*.', 8),
    ('68bf1a7a-f929-5a88-bf9e-55e00ac82a5b'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Où se place l’infinitif dépendant d’un modal, dans une principale ?', 'mcq', '["À la fin de la phrase","Juste après le modal","Devant le sujet","En première position"]'::jsonb, 0, '*Ich muss heute Abend arbeiten.*', 1),
    ('bc6aeef8-11aa-5b73-918e-3aae42fd9ae5'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Comment se conjugue « können » à la 1re personne du singulier ?', 'mcq', '["ich kann","ich könne","ich kanne","ich könnt"]'::jsonb, 0, 'Les modaux n’ont aucune terminaison aux 1re et 3e personnes du singulier.', 2),
    ('15e29bf5-a8a6-5c68-b238-1527ddc5006c'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, '« Ich muss nicht kommen » signifie…', 'mcq', '["Je ne suis pas obligé de venir","Je ne dois pas venir","Je ne peux pas venir","Je ne veux pas venir"]'::jsonb, 0, 'L’interdiction se dit *nicht dürfen* : *Du darfst nicht kommen.*', 3),
    ('256e415c-ca35-5970-bfea-f71c412eb407'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Quel modal exprime une consigne venue d’autrui ?', 'mcq', '["sollen","wollen","können","mögen"]'::jsonb, 0, '*Ich soll den Arzt fragen* : on m’a dit de le faire.', 4),
    ('58d0c88d-955a-5d5f-879e-d68e5dd1d298'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Quel est le prétérit de « müssen » ?', 'mcq', '["musste","müsste","mochte","gemusst"]'::jsonb, 0, 'Sans inflexion : *musste*. *müsste* est le subjonctif II.', 5),
    ('b2dca02e-11d8-59a4-8b32-d2dee04bf55a'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Au parfait, avec un infinitif dépendant, le modal prend la forme du participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le double infinitif : *Ich habe arbeiten müssen.*', 6),
    ('87f37dcb-e749-5278-af78-e6779315f33a'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Comment dire poliment « je voudrais un café » ?', 'mcq', '["Ich möchte einen Kaffee","Ich will einen Kaffee","Ich mag einen Kaffee","Ich muss einen Kaffee"]'::jsonb, 0, '*möchte* est le subjonctif II de *mögen* : la forme polie usuelle.', 7),
    ('5ef1913d-a3fd-5f6a-9667-0ae9babb99e6'::uuid, '74d37f0f-5ac6-5900-b6e4-a0b83552792d'::uuid, 'Quel modal exprime l’autorisation ?', 'mcq', '["dürfen","müssen","wollen","sollen"]'::jsonb, 0, '*Darf ich reinkommen?* — *können* dit la capacité.', 8),
    ('43239378-1d9b-5d48-9225-e92592d7f8a9'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Comment reconnaître un préverbe séparable ?', 'mcq', '["Il porte l’accent du mot","Il commence par be-","Il se termine par -en","Il est toujours plus long"]'::jsonb, 0, '*ÁNrufen* contre *be-SÚCHEN* : le critère s’entend.', 1),
    ('1814aef3-3440-5ed1-b534-af2f5da35a0e'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Dans une principale, où va le préverbe séparable ?', 'mcq', '["À la fin de la phrase","Devant le verbe","Après le sujet","Il reste soudé"]'::jsonb, 0, '*Ich stehe um sieben Uhr auf.*', 2),
    ('cef0127d-d8ab-58f0-887e-9b16a57e085c'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Quel est le participe passé de « aufstehen » ?', 'mcq', '["aufgestanden","geaufstanden","aufstanden","gestandenauf"]'::jsonb, 0, 'Le *ge-* s’intercale entre le préverbe et le radical.', 3),
    ('ca4a661d-4bba-543f-8111-d1718fe0317d'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Quel est le participe passé de « besuchen » ?', 'mcq', '["besucht","gebesucht","besuchen","gesucht"]'::jsonb, 0, 'Les préverbes inséparables (*be-, ver-, er-, ent-*) interdisent le *ge-*.', 4),
    ('c83b0cd7-f71b-500c-9c45-4042bb074baa'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Comment écrit-on « einkaufen » avec « zu » ?', 'mcq', '["einzukaufen","zu einkaufen","einkaufen zu","zueinkaufen"]'::jsonb, 0, 'Le *zu* s’intercale, et le tout s’écrit en un seul mot.', 5),
    ('0509d4d4-418c-5912-8806-ee654355abd1'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'En subordonnée, le préverbe reste détaché.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le verbe conjugué part à la fin et rejoint son préverbe : *…, weil er aufsteht.*', 6),
    ('2b7b1fa3-81cd-5b12-81db-cb18cd2328a5'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, '« übersetzen » est toujours inséparable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Séparable au sens concret (traverser), inséparable au sens figuré (traduire).', 7),
    ('2eb4df5d-76ab-5d56-803b-0a48aa21c420'::uuid, '99a0a870-7a69-5f51-9a81-712f35159f2b'::uuid, 'Que signifie « ankommen » ?', 'mcq', '["Arriver","Venir","Recevoir","Accompagner"]'::jsonb, 0, '*bekommen* = recevoir, *mitkommen* = accompagner : le préverbe fait le sens.', 8),
    ('01936fbc-eccf-517a-8250-5fc2b041dc61'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Quelle est la forme du réfléchi à la 3e personne, à l’accusatif comme au datif ?', 'mcq', '["sich","ihn","ihm","es"]'::jsonb, 0, '*sich* couvre les deux cas à la 3e personne, singulier et pluriel.', 1),
    ('3940ba45-a10e-5f92-a603-599255c0880d'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Quand emploie-t-on le réfléchi au datif ?', 'mcq', '["Quand la phrase contient déjà un COD","Quand le verbe est fort","Quand la phrase est négative","Quand le sujet est au pluriel"]'::jsonb, 0, '*Ich wasche mir die Hände* : *die Hände* est le COD.', 2),
    ('fce2377e-713c-59d4-bbe9-c7552ef56991'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Comment dit-on « je me lave » (sans complément) ?', 'mcq', '["Ich wasche mich","Ich wasche mir","Ich wasche mich die","Ich wasche sich"]'::jsonb, 0, 'Sans COD, le réfléchi reste à l’accusatif.', 3),
    ('d6e820f3-5def-5605-84d0-deea3155b30e'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Où se place le pronom réfléchi dans une principale ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Devant le sujet toujours","Après le participe passé"]'::jsonb, 0, '*Ich freue mich auf die Ferien.*', 4),
    ('5be23905-b8a0-565b-b197-dd93d4f4a502'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, '« sich freuen auf » se construit avec…', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Comme *sich interessieren für* et *sich erinnern an* : préposition + accusatif.', 5),
    ('7667afb0-ee38-585c-85b3-49031d15124c'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, '« aufstehen » est un verbe pronominal en allemand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Se lever » se dit *aufstehen*, sans pronom réfléchi.', 6),
    ('db5c17ea-d503-5b2d-97d7-8765d4f6dd34'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Dans le vouvoiement, « sich » prend une majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Setzen Sie sich bitte!* — seul *Sie* et ses formes possessives la prennent.', 7),
    ('a52ee386-8aba-5f63-b739-54f40e22568c'::uuid, 'ab6360a0-e2f1-59de-84e0-2edc7d77b270'::uuid, 'Comment dit-on « je m’achète un livre » ?', 'mcq', '["Ich kaufe mir ein Buch","Ich kaufe mich ein Buch","Ich kaufe sich ein Buch","Ich kaufe mein Buch"]'::jsonb, 0, 'Il y a un COD (*ein Buch*) : le réfléchi passe au datif.', 8),
    ('ae6c8e27-28fe-548f-94d5-374cf4161f41'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Quelle est la terminaison de la 2e personne du singulier ?', 'mcq', '["-st","-t","-e","-en"]'::jsonb, 0, '*du spielst*, *du lernst*, *du wohnst*.', 1),
    ('6447044f-efe0-519a-9170-617b76bb65da'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Comment se conjugue « arbeiten » à la 3e personne du singulier ?', 'mcq', '["er arbeitet","er arbeitt","er arbeit","er arbeitest"]'::jsonb, 0, 'Radical en *-t* : on intercale un *e* pour pouvoir prononcer.', 2),
    ('34ac4674-256f-53be-8cff-3a2711420674'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Comment se conjugue « heißen » à la 2e personne du singulier ?', 'mcq', '["du heißt","du heißst","du heißest","du heißen"]'::jsonb, 0, 'Après *-s, -ß, -z*, le *-st* perd son *s*.', 3),
    ('a1a7d5c8-7bf2-5d08-b1e4-36fa1b12df59'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Le changement de voyelle des verbes forts touche aussi le pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne concerne que les 2e et 3e personnes du singulier : *wir fahren*, pas *wir fähren*.', 4),
    ('ffa80cce-0de5-588e-a94d-edb30c7e7bb6'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Comment se conjugue « lesen » à la 3e personne du singulier ?', 'mcq', '["er liest","er lest","er läst","er liesst"]'::jsonb, 0, 'Alternance *e → ie*, et le *-st* fusionne avec le *s* du radical.', 5),
    ('22fb6405-777b-58bb-82e8-0e2c56cd6be3'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Comment traduire « demain, je vais à Berlin » ?', 'mcq', '["Morgen fahre ich nach Berlin","Morgen ich fahre nach Berlin","Morgen werde ich fahren nach Berlin","Morgen ich werde nach Berlin"]'::jsonb, 0, 'Le présent suffit à dire l’avenir dès qu’un adverbe de temps le précise.', 6),
    ('46f2310b-3973-56bc-a47f-fbdc7035c5e9'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Avec « seit », l’allemand emploie le parfait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le présent : *Ich lerne seit drei Jahren Deutsch.*', 7),
    ('10ee3314-0430-5ce7-a7d8-0656076ba3f1'::uuid, '87a4591a-388e-5ffa-8207-85a5d866eb0b'::uuid, 'Comment se conjugue « werden » à la 2e personne du singulier ?', 'mcq', '["du wirst","du werdest","du werdst","du wird"]'::jsonb, 0, '*werde, wirst, wird, werden, werdet, werden*.', 8),
    ('ae836463-043e-5e92-a08c-1c563d68ed78'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Le prétérit est le temps…', 'mcq', '["De l’écrit et du récit","De l’oral courant","Du futur proche","De l’hypothèse"]'::jsonb, 0, 'À l’oral, on raconte au parfait — sauf pour *sein*, *haben* et les modaux.', 1),
    ('7f8243f0-2e83-524e-9d44-5fc3d6cfb9d6'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quelle est la marque du prétérit des verbes faibles ?', 'mcq', '["-te","-en","-st","Un changement de voyelle"]'::jsonb, 0, '*ich spielte*, *er spielte* : les deux formes sont identiques.', 2),
    ('71757dbb-874a-505c-8ec1-fe67971c4cbf'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quel est le prétérit de « gehen » ?', 'mcq', '["ging","gehte","gang","gegangen"]'::jsonb, 0, 'Verbe fort : *gehen → ging → gegangen*.', 3),
    ('f1c0e281-7943-5d81-be2f-df6f336edb2a'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Aux 1re et 3e personnes, un verbe fort au prétérit ne prend aucune terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*ich ging*, *er ging* : la forme est nue.', 4),
    ('575cd22c-a47f-5969-90e8-42e1ca9adef3'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quel est le prétérit de « wissen » ?', 'mcq', '["wusste","wisste","wieß","gewusst"]'::jsonb, 0, 'Verbe mixte : radical modifié, terminaison faible.', 5),
    ('a9f90b0e-9e13-5eee-a485-11a8435065b5'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quels verbes emploie-t-on au prétérit même à l’oral ?', 'mcq', '["sein, haben, werden et les modaux","Tous les verbes forts","Les verbes en -ieren","Aucun"]'::jsonb, 0, '*Ich war müde* est bien plus naturel que *ich bin müde gewesen*.', 6),
    ('3b86dc7a-96ec-588f-a01f-c4767bfd2294'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Prétérit de haben ou sein + participe II","Présent de werden + infinitif","Prétérit + zu","Parfait + würde"]'::jsonb, 0, '*Ich hatte gegessen*, *er war gegangen* — surtout après *nachdem*.', 7),
    ('80fc8954-e9a2-5bc0-990f-9b7c726d4ac1'::uuid, 'eb6f6cd8-195f-52d4-b977-e391a7f357c5'::uuid, 'Quel est le prétérit de « nehmen » ?', 'mcq', '["nahm","nehmte","nimmte","genommen"]'::jsonb, 0, 'Alternance forte : *nehmen → nahm → genommen*.', 8),
    ('74e87172-cb76-5cf7-a2a8-b68878275c52'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Où se place le participe II dans une principale au parfait ?', 'mcq', '["À la fin de la phrase","Juste après l’auxiliaire","En deuxième position","Devant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : l’auxiliaire ouvre, le participe ferme.', 1),
    ('6b60e253-47b0-5726-9127-b1a6385f61fc'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Quel est le participe II de « fahren » ?', 'mcq', '["gefahren","gefahrt","fahren","gefuhr"]'::jsonb, 0, 'Verbe fort : *ge-* + radical + *-en*.', 2),
    ('9775ed58-25e0-5586-9246-17a2eee4a074'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Quel auxiliaire prend « einschlafen » au parfait ?', 'mcq', '["sein","haben","werden","Les deux"]'::jsonb, 0, 'C’est un verbe de changement d’état : *Ich bin eingeschlafen.*', 3),
    ('f93935ee-ddc0-5d84-8bf1-95fef1ecd45b'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Quel est le participe II de « telefonieren » ?', 'mcq', '["telefoniert","getelefoniert","telefonierte","getelefonierte"]'::jsonb, 0, 'Les verbes en *-ieren* n’ont jamais de *ge-*.', 4),
    ('4766da93-300f-5de1-b36d-5c40777434d0'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Quel est le participe II de « einkaufen » ?', 'mcq', '["eingekauft","geeinkauft","einkauft","gekaufein"]'::jsonb, 0, 'Préverbe séparable : le *ge-* s’intercale.', 5),
    ('c30ccec0-9677-5796-aae7-fe88c6422d8e'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, '« Ich habe das Auto gefahren » est une faute.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Employé avec un COD, *fahren* prend *haben*.', 6),
    ('330ee6fe-e2b8-572b-9630-28977ad1cec3'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'En subordonnée, où se place l’auxiliaire au parfait ?', 'mcq', '["Après le participe, à la toute fin","En deuxième position","Devant le participe","Il disparaît"]'::jsonb, 0, '*…, weil ich einen Film gesehen habe.*', 7),
    ('63aae9cb-3254-5ca9-bc8d-10a7c034d264'::uuid, 'e6ec77fe-3945-5916-a443-7d573504a7ce'::uuid, 'Le parfait est le passé de la conversation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le prétérit, lui, est celui du récit écrit.', 8),
    ('552ec4b1-41bd-5409-8c10-5b31ab132e29'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Comment se forme le Futur I ?', 'mcq', '["werden + infinitif","sein + participe II","haben + infinitif","werden + participe II"]'::jsonb, 0, '*Ich werde morgen fahren*, l’infinitif en fin de phrase.', 1),
    ('b480ea5c-e789-5eb8-b144-aded09a65033'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Comment se conjugue « werden » à la 3e personne du singulier ?', 'mcq', '["er wird","er werd","er werdet","er wurde"]'::jsonb, 0, '*ich werde, du wirst, er wird…*', 2),
    ('03e9b378-10c1-555c-929a-16a0639deb55'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Quand le présent suffit-il à exprimer le futur ?', 'mcq', '["Quand un adverbe de temps précise l’avenir","Jamais","Uniquement avec les modaux","Uniquement à l’écrit"]'::jsonb, 0, '*Morgen fahre ich nach Berlin* est la forme la plus courante.', 3),
    ('a371a98b-6ee2-58b3-a8d5-b7957ee4f883'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, '« Er wird wohl krank sein » signifie…', 'mcq', '["Il doit être malade (supposition)","Il sera malade demain","Il est tombé malade","Il veut être malade"]'::jsonb, 0, 'Le futur exprime aussi une hypothèse sur le présent, souvent avec *wohl*.', 4),
    ('f96d3743-f6d2-56ee-ad41-b64d24387b40'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, '« Das Haus wird gebaut » est un futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un passif : *werden* + participe II. Le futur demanderait un infinitif.', 5),
    ('6037feab-9b84-5a49-96fa-765c36e5960c'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Que signifie « Er wird Arzt » ?', 'mcq', '["Il devient médecin","Il sera médecin demain","Il est fait médecin","Il doit être médecin"]'::jsonb, 0, '*werden* + nom : c’est le verbe plein « devenir ».', 6),
    ('8e388a0a-348f-5edd-95f9-14be1c4f6776'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'En subordonnée, quel mot ferme une phrase au futur ?', 'mcq', '["werden conjugué","L’infinitif","Le sujet","La conjonction"]'::jsonb, 0, '*…, dass er kommen wird.*', 7),
    ('216eebbf-ace3-533c-accf-ee1db7eb6062'::uuid, '4f657556-e355-566b-bdae-c9b928b2a266'::uuid, 'Le Futur II exprime une action achevée dans l’avenir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Bis morgen werde ich das Buch gelesen haben* — ou une supposition sur le passé.', 8),
    ('21657c76-1af2-5a38-bfd3-920acf1cee0a'::uuid, 'c9d5b452-a3ee-51e0-8674-6282d18b2670'::uuid, 'Quelle est la forme d’impératif de « kommen » pour « du » ?', 'mcq', '["Komm!","Kommst!","Komme du!","Kommen!"]'::jsonb, 0, 'Radical sans terminaison et sans pronom.', 1),
    ('7d28f16f-1bf3-51f9-9851-3f912afd49c5'::uuid, 'c9d5b452-a3ee-51e0-8674-6282d18b2670'::uuid, 'Comment dit-on « Donne ! » (du) ?', 'mcq', '["Gib!","Geb!","Gebe!","Gibst!"]'::jsonb, 0, 'L’alternance *e → i* se maintient à l’impératif.', 2),
    ('a580a2d0-c2eb-57f2-84a2-01420d8e6cb7'::uuid, 'c9d5b452-a3ee-51e0-8674-6282d18b2670'::uuid, '« Fahre! » garde-t-il l’inflexion de « du fährst » ?', 'mcq', '["Non, on dit Fahr!","Oui, on dit Fähr!","Oui, on dit Fährst!","Les deux sont possibles"]'::jsonb, 0, 'L’alternance *a → ä* disparaît à l’impératif.', 3),
